-- =====================================================================
-- SCCVI - Tabla de referencia de la OMS (metodo LMS), edad en DIAS
-- Fuente: OMS - WHO Child Growth Standards, tablas expandidas (z-scores),
--   0 a 5 anios (dia 0 a 1856):
--   * peso_edad  = peso para la edad (weight-for-age)
--   * talla_edad = longitud/talla para la edad (length/height-for-age)
-- sexo: 'M' = ninos (boys), 'F' = ninas (girls)
--
-- Este script es AUTOCONTENIDO: borra y vuelve a crear la tabla.
-- Se puede ejecutar de nuevo sin problema.
-- =====================================================================

BEGIN;

DROP TABLE IF EXISTS oms_referencia;

CREATE TABLE oms_referencia (
  id         serial PRIMARY KEY,
  indicador  varchar(20) NOT NULL,
  sexo       char(1) NOT NULL,
  edad_dias  int NOT NULL,
  l          decimal(10,5) NOT NULL,
  m          decimal(10,5) NOT NULL,
  s          decimal(10,5) NOT NULL,
  CONSTRAINT chk_oms_indicador CHECK (indicador IN ('peso_edad', 'talla_edad')),
  CONSTRAINT chk_oms_sexo      CHECK (sexo IN ('M', 'F')),
  CONSTRAINT chk_oms_edad      CHECK (edad_dias BETWEEN 0 AND 1856),
  CONSTRAINT uq_oms_referencia UNIQUE (indicador, sexo, edad_dias)
);

